            let operation = match operation {
                Expr::UnsignedAdd { .. } => "addition",
                Expr::UnsignedSubtract { .. } => "subtraction",
                Expr::UnsignedMultiply { .. } => "multiplication",
                _ => unreachable!("unsigned arithmetic caller"),
